            'notification.contractUpdate.title' => ['en' => 'Contract Update', 'uz' => 'Shartnoma yangilandi', 'ru' => 'Обновление контракта', 'ar' => 'تحديث العقد'],
            'notification.paymentUpdate.title' => ['en' => 'Payment Update', 'uz' => 'To‘lov yangilandi', 'ru' => 'Обновление платежа', 'ar' => 'تحديث الدفع'],
            'notification.contractUpdate.message' => ['en' => 'Your contract status has been updated.', 'uz' => 'Shartnomangiz holati yangilandi.', 'ru' => 'Статус вашего контракта обновлен.', 'ar' => 'تم تحديث حالة عقدك.'],
            'notification.paymentUpdate.message' => ['en' => 'Your payment status has been updated.', 'uz' => 'To‘lov holati yangilandi.', 'ru' => 'Статус вашего платежа обновлен.', 'ar' => 'تم تحديث حالة دفعتك.'],
        ];

        foreach ($this->applicationStatuses() as $status => $labels) {
            $keys["status.{$status}"] = $labels;
        }

        foreach ($keys as $path => $values) {
            [$group, $key] = explode('.', $path, 2);
            $translationKey = TranslationKey::updateOrCreate(
                ['group' => $group, 'key' => $key],
                ['description' => 'Student system UI: '.$path, 'is_system' => true]
            );

            foreach ($this->locales as $locale) {
                TranslationValue::updateOrCreate(
                    ['translation_key_id' => $translationKey->id, 'locale' => $locale],
                    ['value' => $values[$locale] ?? $values['en']]
                );
            }
        }
    }

